  let d;
  if (typeof ts === 'number') d = new Date(ts > 1e11 ? ts : ts * 1000);
  else d = new Date(ts);
  if (!(d instanceof Date) || Number.isNaN(d.getTime())) return '—'
  const p = n => String(n).padStart(2, '0');
