/** 大小文案（GB / TB）。 */
function gbText(v) {
  const n = Number(v);
  if (!Number.isFinite(n) || n <= 0) return '—'
  return n >= 1024 ? `${(n / 1024).toFixed(2)} TB` : `${n.toFixed(2)} GB`
}

